#include <automation/orchestration/control_runtime.hpp>
#include <chrono>
namespace rebuntu::orchestration {
ApplyResult ControlRuntime::apply(const management::Request&r,bool authorized,bool confirmed){auto start=std::chrono::steady_clock::now();auto plan=domains_.prepare(r);policy::Context context; context.actor="operator"; context.elevated=authorized; context.interactive=confirmed; if(authorized) context.capabilities.insert("secrets.write"); auto decision=policy_.evaluate(plan,context);ApplyResult out;out.transaction_id="tx-"+std::to_string(++sequence_);if(!decision.allowed){out.message=decision.reasons.empty()?"policy denied":decision.reasons.front();telemetry_.record({{},"control","apply",r.target,false,std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start),{{"reason",out.message}}});return out;}out.accepted=true;std::string before;auto old=state_.get(r.target,r.property);if(old)before=old->value;backend::Command cmd{"rebuntu-domain-apply",{plan.domain,plan.target,r.property,r.value},plan.privileged};auto br=backend_.execute(cmd);out.applied=br.exit_code==0&&!br.timed_out;out.message=out.applied?"applied":br.stderr_text;journal_.append({out.transaction_id,plan.domain,plan.target,r.property,before,r.value,out.applied?"committed":"failed"});if(out.applied)domains_.observe(r,"control-runtime");telemetry_.record({{},"control","apply",r.target,out.applied,std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start),{{"transaction",out.transaction_id},{"domain",plan.domain}}});return out;}
}
